ns16:scriptTask.ns16:script:
/**----------------------------------------------------NOTES-----------------------------------------------------------------------**/
// Document Details is commented !!
// Accountee has been removed !!
/**---------------------------------------------------------------------------------------------------------------------------------**/

tw.local.Contract_Details_Full = new tw.object.toolkit.NBEINTT.Contract_Details_Full_1();

tw.local.Contract_Details_Full.ProductCode = tw.local.ContractDetails.ContractCreation.productCode.value;
tw.local.Contract_Details_Full.Currency = tw.local.ContractDetails.ContractCreation.currency;
tw.local.Contract_Details_Full.BillStage = "FIN";
tw.local.Contract_Details_Full.Amount = tw.local.ContractDetails.ContractCreation.amount;
tw.local.Contract_Details_Full.CCY = tw.local.ContractDetails.FinancialDetailsBR.currency.value;
tw.local.Contract_Details_Full.OutstandingAmount = tw.local.ContractDetails.FinancialDetailsFO.outstandingAmount;
tw.local.Contract_Details_Full.MaturityDate = formatDate(tw.local.ContractDetails.ContractCreation.maturityDate);
tw.local.Contract_Details_Full.CustomerId = tw.local.ContractDetails.CustomerInfo.cif;
tw.local.Contract_Details_Full.PartyType = "DRAWER";
tw.local.Contract_Details_Full.BranchCode = tw.local.branchCode;
tw.local.Contract_Details_Full.USEREFNO = tw.local.ContractDetails.ContractCreation.userReference;
tw.local.Contract_Details_Full.VALDT = formatDate(tw.local.ContractDetails.ContractCreation.valueDate);
tw.local.Contract_Details_Full.TENOR_DAYS = tw.local.ContractDetails.ContractCreation.tenorDays;
tw.local.Contract_Details_Full.TRANSITDAYS = tw.local.ContractDetails.ContractCreation.transitDays;
tw.local.Contract_Details_Full.BASDT = formatDate(tw.local.ContractDetails.ContractCreation.baseDate);
tw.local.Contract_Details_Full.OPERATION = tw.local.ContractDetails.BasicDetails.operationType.value;
tw.local.Contract_Details_Full.FROMDATE = tw.local.Contract_Details_Full.BASDT;
tw.local.Contract_Details_Full.TODATE = tw.local.Contract_Details_Full.MaturityDate;

// tw.local.Contract_Details_Full.Maker = "";
// tw.local.Contract_Details_Full.Checker = "";
// tw.local.Contract_Details_Full.TransStatus = "";
 tw.local.Contract_Details_Full.AuthStatus = "U";
// tw.local.Contract_Details_Full.LC_CUST = "";
// tw.local.Contract_Details_Full.LCREFNO = "";
//tw.local.Contract_Details_Full.VDATECR = tw.local.ContractDetails.ContractLiquidation.creditValueDate;
//tw.local.Contract_Details_Full.DRVALDT = tw.local.ContractDetails.ContractLiquidation.debitValueDate;
// tw.local.Contract_Details_Full.TXNDT = new TWDate();
// tw.local.Contract_Details_Full.USE_LC_REF_MESS = "";
//tw.local.Contract_Details_Full.ACPFRMDT = new TWDate(); //?????????????????
//tw.local.Contract_Details_Full.ACPTODT = new TWDate(); //?????????????????
// tw.local.Contract_Details_Full.TRANSFERCOLLATFROMLC = "";
// tw.local.Contract_Details_Full.TFR_COLL_AMT = 0.0; //?????????????????
// tw.local.Contract_Details_Full.CollateralCurrency = "";
// tw.local.Contract_Details_Full.CollateralAmount = 0.0;
// tw.local.Contract_Details_Full.LimitMonitoringFlag = "";
// tw.local.Contract_Details_Full.EXTREFNO = "";

/**---------------------------------------------Parties-------------------------------------------------------**/
tw.local.Contract_Details_Full.Contract_Parties = new tw.object.listOf.toolkit.NBEINTT.Contract_Parties_8();
//Drawer
tw.local.Contract_Details_Full.Contract_Parties[0] = new tw.object.toolkit.NBEINTT.Contract_Parties_8();
tw.local.Contract_Details_Full.Contract_Parties[0].PartyLang = tw.local.ContractDetails.Parties.Drawer.Language;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyCountryCode = tw.local.ContractDetails.Parties.Drawer.country;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyRefNum = tw.local.ContractDetails.Parties.Drawer.Reference;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyName = tw.local.ContractDetails.Parties.Drawer.partyName;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyAddress1 = tw.local.ContractDetails.Parties.Drawer.address1;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyAddress2 = tw.local.ContractDetails.Parties.Drawer.address2;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyAddress3 = tw.local.ContractDetails.Parties.Drawer.address3;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyId = tw.local.ContractDetails.Parties.Drawer.partyId;
tw.local.Contract_Details_Full.Contract_Parties[0].PartyType = "DRAWER";
//tw.local.Contract_Details_Full.Contract_Parties[0].PartyAddress4 = "";

//Drawee
tw.local.Contract_Details_Full.Contract_Parties[1] = new tw.object.toolkit.NBEINTT.Contract_Parties_8();
tw.local.Contract_Details_Full.Contract_Parties[1].PartyLang = tw.local.ContractDetails.Parties.Drawee.Language;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyCountryCode = tw.local.ContractDetails.Parties.Drawee.country;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyRefNum = tw.local.ContractDetails.Parties.Drawee.Reference;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyName = tw.local.ContractDetails.Parties.Drawee.partyName;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyAddress1 = tw.local.ContractDetails.Parties.Drawee.address1;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyAddress2 = tw.local.ContractDetails.Parties.Drawee.address2;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyAddress3 = tw.local.ContractDetails.Parties.Drawee.address3;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyId = tw.local.ContractDetails.Parties.Drawee.partyId;
tw.local.Contract_Details_Full.Contract_Parties[1].PartyType = "DRAWEE";
//tw.local.Contract_Details_Full.Contract_Parties[1].PartyAddress4 = "";

//collectingBank
tw.local.Contract_Details_Full.Contract_Parties[2] = new tw.object.toolkit.NBEINTT.Contract_Parties_8();
tw.local.Contract_Details_Full.Contract_Parties[2].PartyLang = tw.local.ContractDetails.Parties.collectingBank.language;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyCountryCode = tw.local.ContractDetails.Parties.collectingBank.country;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyRefNum = tw.local.ContractDetails.Parties.collectingBank.reference;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyName = tw.local.ContractDetails.Parties.collectingBank.name;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress1 = tw.local.ContractDetails.Parties.collectingBank.address1;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress2 = tw.local.ContractDetails.Parties.collectingBank.address2;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress3 = tw.local.ContractDetails.Parties.collectingBank.address3;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyId = tw.local.ContractDetails.Parties.collectingBank.id;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyType = "COLLECTING BANK";
tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress = new tw.object.listOf.toolkit.NBEINTT.PartyAddress();
tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress[0] = new tw.object.toolkit.NBEINTT.PartyAddress();
tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress[0].Media = tw.local.ContractDetails.Parties.collectingBank.media;
tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress[0].Address = tw.local.ContractDetails.Parties.collectingBank.address;
//tw.local.Contract_Details_Full.Contract_Parties[2].PartyAddress4 = "";

//caseInNeed
if (tw.local.ContractDetails.Parties.caseInNeed && tw.local.ContractDetails.Parties.caseInNeed.partyId) {
	tw.local.Contract_Details_Full.Contract_Parties[3] = new tw.object.toolkit.NBEINTT.Contract_Parties_8();
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyLang = tw.local.ContractDetails.Parties.caseInNeed.language;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyCountryCode = tw.local.ContractDetails.Parties.caseInNeed.country;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyRefNum = tw.local.ContractDetails.Parties.caseInNeed.refrence;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyName = tw.local.ContractDetails.Parties.caseInNeed.partyName;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyAddress1 = tw.local.ContractDetails.Parties.caseInNeed.address1;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyAddress2 = tw.local.ContractDetails.Parties.caseInNeed.address2;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyAddress3 = tw.local.ContractDetails.Parties.caseInNeed.address3;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyId = tw.local.ContractDetails.Parties.caseInNeed.partyId;
	tw.local.Contract_Details_Full.Contract_Parties[3].PartyType = "CASE IN NEED";
	//	tw.local.Contract_Details_Full.Contract_Parties[3].PartyAddress4 = "";
}

/**---------------------------------------------TXNUDFDETAILS-------------------------------------------------------**/
tw.local.Contract_Details_Full.TXNUDFDETAILS = new tw.object.listOf.toolkit.NBEINTT.TXNUDFDETAILS_6();
addTXNUDFDETAILS("GOODS_ARB_DESCRIPTION_CBE", tw.local.ContractDetails.BasicDetails.commodityDescription);
addTXNUDFDETAILS("GOODS_DSC_CBE", tw.local.ContractDetails.ProductShipmentDetails.CBEGoods.value);
addTXNUDFDETAILS("GOVERNMENT_COTTON", tw.local.ContractDetails.ProductShipmentDetails.governmentCotton ? "Yes" : "No");
addTXNUDFDETAILS("INCO TERM", tw.local.ContractDetails.ProductShipmentDetails.incoterms.name);
//tw.local.ContractDetails.BasicDetails.paymentTerms.name == "004";
if (tw.local.ContractDetails.ContractCreation.productCode.value != ""+tw.epv.ProductCode.OMBC) {
	addTXNUDFDETAILS("GOOD_DESTINATION", tw.local.ContractDetails.ImporterDetails.goodDestination.value);
}

/**---------------------------------------------Charges and Settlements-------------------------------------------------**/
// tw.local.Contract_Details_Full.Settlements.LATEVNSEQNO = "";
if (tw.local.ContractDetails.ChargesAndCommissions.length > 0) {
	tw.local.Contract_Details_Full.Charges = new tw.object.listOf.toolkit.NBEINTT.Charges_25();
	tw.local.Contract_Details_Full.Charges[0] = new tw.object.toolkit.NBEINTT.Charges_25();
	tw.local.Contract_Details_Full.Charges[0].Charge_Association = new tw.object.listOf.toolkit.NBEINTT.Charge_Association_18();
	tw.local.Contract_Details_Full.Charges[0].ChargeApplication = new tw.object.listOf.toolkit.NBEINTT.ChargeApplication_5();

	tw.local.Contract_Details_Full.Settlements = new tw.object.toolkit.NBEINTT.Settlements_26();
	tw.local.Contract_Details_Full.Settlements.Contract_Settlement = new tw.object.listOf.toolkit.NBEINTT.Contract_Settlement_21();
	var j = 0;
	for (var i = 0; i < tw.local.ContractDetails.ChargesAndCommissions.length; i++) {
		tw.local.Contract_Details_Full.Charges[0].Charge_Association[i] = new tw.object.toolkit.NBEINTT.Charge_Association_18();
		tw.local.Contract_Details_Full.Charges[0].Charge_Association[i].COMPNT = tw.local.ContractDetails.ChargesAndCommissions[i].component;
		tw.local.Contract_Details_Full.Charges[0].Charge_Association[i].CreateSn = "1";

		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i] = new tw.object.toolkit.NBEINTT.ChargeApplication_5();
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].COMPNT = tw.local.ContractDetails.ChargesAndCommissions[i].component;
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].CHRGAMT = tw.local.ContractDetails.ChargesAndCommissions[i].changeAmount;
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].WAIVER = tw.local.ContractDetails.ChargesAndCommissions[i].waiver ? "Y" : "N";
		tw.local.Contract_Details_Full.Charges[0].ChargeApplication[i].CreateSn = "1";
		// tw.local.Contract_Details_Full.Charges[0].ChargeApplication[0].TGCCY = "";
		//----------------------------------------------------------------------------------
		if (!tw.local.ContractDetails.ChargesAndCommissions[i].waiver) {
			tw.local.Contract_Details_Full.Settlements.Contract_Settlement[j] = new tw.object.toolkit.NBEINTT.Contract_Settlement_21();
			tw.local.Contract_Details_Full.Settlements.Contract_Settlement[j].COMPNT = tw.local.ContractDetails.ChargesAndCommissions[i].component;
			tw.local.Contract_Details_Full.Settlements.Contract_Settlement[j].ACCBRN = tw.local.ContractDetails.ChargesAndCommissions[i].debitedAccount.branchCode;
			tw.local.Contract_Details_Full.Settlements.Contract_Settlement[j].ACC = tw.local.ContractDetails.ChargesAndCommissions[i].debitedAccount.glAccountNo ? tw.local.ContractDetails.ChargesAndCommissions[i].debitedAccount.glAccountNo : tw.local.ContractDetails.ChargesAndCommissions[i].debitedAccount.customerAccountNo;
			tw.local.Contract_Details_Full.Settlements.Contract_Settlement[j].ACCCCY = tw.local.ContractDetails.ChargesAndCommissions[i].debitedAccount.currency.value;
			// tw.local.Contract_Details_Full.Settlements.Contract_Settlement[i].EXRATE = 0.0;
			// tw.local.Contract_Details_Full.Settlements.Contract_Settlement[i].TAGCCY = "";
			j++;
		}
	}
}

/**------------------------------------------------Contract_Multitnr----------------------------------------------------**/
if (tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates.length > 0) {
	tw.local.Contract_Details_Full.ContractMultitnr = new tw.object.listOf.toolkit.NBEINTT.ContractMultitnr();
	for (var i = 0; i < tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates.length; i++) {
		tw.local.Contract_Details_Full.ContractMultitnr[i] = new tw.object.toolkit.NBEINTT.ContractMultitnr();
		tw.local.Contract_Details_Full.ContractMultitnr[i].SERIALNUM = i-1;
		tw.local.Contract_Details_Full.ContractMultitnr[i].BASDATE = formatDate(tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].instalmentBaseDate);
		tw.local.Contract_Details_Full.ContractMultitnr[i].VALUDATE = tw.local.Contract_Details_Full.VALDT;
		tw.local.Contract_Details_Full.ContractMultitnr[i].TNOR = tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].instalmentTenorDays || 0;
		tw.local.Contract_Details_Full.ContractMultitnr[i].BILLAMNT = tw.local.ContractDetails.FinancialDetailsFO.multiTenorDates[i].amount;
		// tw.local.Contract_Details_Full.ContractMultitnr[i].TRANSTDAYS = 0.0;
		// tw.local.Contract_Details_Full.ContractMultitnr[i].SPLITPCT = 0.0;
	}
}

/**-----------------------------------------------------------------------------------------------------------------------------------------**/
//Advice
// tw.local.Contract_Details_Full.Adice = new tw.object.toolkit.NBEINTT.Adice_1();
// tw.local.Contract_Details_Full.Adice.Fft = new tw.object.listOf.toolkit.NBEINTT.Fft_1();
// tw.local.Contract_Details_Full.Adice.Fft[0] = new tw.object.toolkit.NBEINTT.Fft_1();

//Interest
// tw.local.Contract_Details_Full.Intrest = new tw.object.listOf.toolkit.NBEINTT.IntrestDetails();
// tw.local.Contract_Details_Full.Intrest[0] = new tw.object.toolkit.NBEINTT.IntrestDetails();

// ContractGoodsDetails
// tw.local.Contract_Details_Full.ContractGoodsDetails = new tw.object.listOf.toolkit.NBEINTT.ContractGoodsDetails();
// tw.local.Contract_Details_Full.ContractGoodsDetails[0] = new tw.object.toolkit.NBEINTT.ContractGoodsDetails();

//Party_Limits
// tw.local.Contract_Details_Full.Party_Limits = new tw.object.listOf.toolkit.NBEINTT.Party_Limits_4();
// Document_Details
// tw.local.Contract_Details_Full.Document_Details = new tw.object.listOf.toolkit.NBEINTT.Document_Details_9();
//Goods
// tw.local.Contract_Details_Full.GoodsDetails = new tw.object.toolkit.NBEINTT.GoodsDetails();
//Linkages
// tw.local.Contract_Details_Full.Linkages = new tw.object.listOf.toolkit.NBEINTT.LinkageDetails();
// tw.local.Contract_Details_Full.Linkages[0] = new tw.object.toolkit.NBEINTT.LinkageDetails();
if (!!tw.local.ContractDetails.ContractCreation.HScode && !!tw.local.ContractDetails.ContractCreation.HScode.value) {
      tw.local.Contract_Details_Full.GoodsDetails = new tw.object.toolkit.NBEINTT.GoodsDetails();
   	tw.local.Contract_Details_Full.GoodsDetails.GoodsCode = tw.local.ContractDetails.ContractCreation.HScode.name ;
   	tw.local.Contract_Details_Full.GoodsDetails.GoodsDescription = tw.local.ContractDetails.ContractCreation.HScode.value;
   	
   	tw.local.Contract_Details_Full.ContractGoodsDetails = new tw.object.listOf.toolkit.NBEINTT.ContractGoodsDetails;
   	tw.local.Contract_Details_Full.ContractGoodsDetails[0] = new tw.object.toolkit.NBEINTT.ContractGoodsDetails;
   	tw.local.Contract_Details_Full.ContractGoodsDetails[0].GoodsCode = tw.local.ContractDetails.ContractCreation.HScode.name;
	tw.local.Contract_Details_Full.ContractGoodsDetails[0].GoodsDescription = tw.local.ContractDetails.ContractCreation.HScode.value;

}
/**--------------------------------------------------------HELPER FUNCTIONS-----------------------------------------------------------**/

function formatDate(date) {
	return date.format("yyyy-MM-dd");
}

function addTXNUDFDETAILS(fieldName, fieldValue) {
	if (fieldValue !== null && fieldValue !== undefined && fieldValue !== "") {
		var detail = new tw.object.toolkit.NBEINTT.TXNUDFDETAILS_6();
		var len = tw.local.Contract_Details_Full.TXNUDFDETAILS.listLength;
		detail.FLDNAME = fieldName;
		detail.FLDVAL = fieldValue;
		tw.local.Contract_Details_Full.TXNUDFDETAILS.insertIntoList(len, detail);
	}
}
